SELECT I.ID, I.NOME_CRITERIO_MANUAL AS CRITERIO, ROUND(I.VALOR_UNITARIO, 2) AS VALOR_UNITARIO, ROUND(I.QUANTIDADE, 3) AS QUANTIDADE_TON, ROUND(I.VALOR_TOTAL_ITEM, 2) AS VALOR_TOTAL FROM ITEM_LANCAMENTO I WHERE I.CODPARC = :VAR_PARCEIRO_SELECIONADO AND I.DT_LANCAMENTO BETWEEN :VAR_PERIODO_INICIO AND :VAR_PERIODO_FIM AND I.ORIGEM = 'Manual' ORDER BY I.DT_LANCAMENTO DESC